1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { AutoRefresh } from "@/components/AutoRefresh";
4	import { EmptyState } from "@/components/ui/primitives";
5	import { PortalHero } from "@/components/portal/PortalHero";
6	import { DeployButton } from "@/components/customer/DeployButton";
7	import { ServersList, type ServerRow } from "@/components/customer/ServersList";
8	import { effectiveDiskGB } from "@/lib/extra-disk";
9	
10	export const dynamic = "force-dynamic";
11	
12	export default async function ServersPage() {
13	  const user = await requireUser();
14	  const servers = await db.server.findMany({
15	    // NxCloud instances are backed by a Server but surfaced as their own product
16	    // under /dashboard/nxcloud, so they're hidden from the raw VPS list here.
17	    where: { userId: user.id, nxcloudInstance: { is: null } },
18	    include: { plan: true, osTemplate: true, project: true },
19	    orderBy: { createdAt: "desc" },
20	  });
21	
22	  const transitional = servers.some((s) =>
23	    ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)
24	  );
25	
26	  const rows: ServerRow[] = servers.map((s) => ({
27	    id: s.id,
28	    hostname: s.hostname,
29	    status: s.status,
30	    isFree: s.isFree,
31	    // Effective disk = plan allowance + any separately-purchased extra disk.
32	    planLine: `${s.plan.name} · ${s.plan.cpuCores} vCPU · ${s.plan.ramMB / 1024} GB · ${effectiveDiskGB(s.plan.diskGB, s.extraDiskGB)} GB`,
33	    osName: s.osTemplate.name,
34	    project: s.project ? { name: s.project.name, color: s.project.color } : null,
35	    endpoint: s.sshPort ? `${process.env.PUBLIC_IP}:${s.sshPort}` : null,
36	    created: s.createdAt.toISOString().slice(0, 10),
37	  }));
38	
39	  return (
40	    <div className="space-y-6">
41	      {transitional && <AutoRefresh />}
42	      <PortalHero variant="servers" title="Servers" sub="All virtual machines on your account.">
43	        <DeployButton href="/dashboard/deploy">Deploy server</DeployButton>
44	      </PortalHero>
45	
46	      {servers.length === 0 ? (
47	        <EmptyState
48	          title="No servers yet"
49	          sub="Deploy your first NVMe-backed VPS — it takes under two minutes from click to SSH."
50	          action={
51	            <DeployButton href="/dashboard/deploy">Deploy your first server</DeployButton>
52	          }
53	        />
54	      ) : (
55	        <ServersList servers={rows} />
56	      )}
57	    </div>
58	  );
59	}
