53	function fmtUptime(seconds: number): string {
54	  if (!seconds || seconds <= 0) return "—";
55	  const d = Math.floor(seconds / 86400);
56	  const h = Math.floor((seconds % 86400) / 3600);
57	  const m = Math.floor((seconds % 3600) / 60);
58	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
59	}
60	
61	type LiveStats = {
62	  cpu?: number;
63	  mem?: number;
64	  maxmem?: number;
65	  uptime?: number;
66	  netin?: number;
67	  netout?: number;
68	} | null;
69	
70	export default async function ServerPage({
71	  params,
72	  searchParams,
73	}: {
74	  params: Promise<{ id: string }>;
75	  searchParams: Promise<{ tab?: string }>;
76	}) {
77	  const [{ id }, { tab }] = await Promise.all([params, searchParams]);
78	  const user = await requireUser();
79	  const server = await db.server.findUnique({
80	    where: { id },
81	    include: {
82	      plan: true,
83	      osTemplate: true,
84	      project: true,
85	      portForwards: { orderBy: { publicPort: "asc" } },
86	      firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] },
87	      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
88	      dedicatedIp: true,
89	      // Needed to price a renewal correctly: a game server bills its game plan's
90	      // flat price, not the base VPS plan's term price.
91	      gamePlan: true,
92	    },
93	  });
94	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();
95	
96	  // Root password may be stored encrypted-at-rest (rootPasswordEnc); resolve the
97	  // display value through the decrypt fallback (legacy plaintext rows still work).
98	  const rootPassword = serverRootPassword(server);
99	
100	  const [projects, activePlans, osTemplates, extraDiskPriceCents, backupPlusCents, annualPct] = await Promise.all([
101	    db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
102	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
103	    db.osTemplate.findMany({
104	      where: { active: true, category: "PLAIN_OS" },
105	      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
106	    }),
107	    extraDiskPerGbCents(),
108	    backupPlusMonthlyCents(),
109	    // Live annual discount — feeds the "Renew now" quote below AND the resize
110	    // pickers, so an annual server's renewal/upgrade/downgrade all price against the
111	    // same rate it was sold at.
112	    annualDiscountPct(),
113	  ]);
114	
115	  // VAT/GST for the SERVER OWNER (Finding 1), resolved from their billing country.
116	  const owner =
117	    server.userId === user.id ? user : (await db.user.findUnique({ where: { id: server.userId } })) ?? user;
118	  const renewTaxCtx = await taxContextForUser(owner);
119	
120	  // What "Renew now" will actually charge, priced through the SAME function the
121	  // action charges through, so the button cannot quote one figure and take
122	  // another. See lib/renewal-quote.ts for the incident.
123	  const renewQuote = renewalQuote(
124	    {
125	      termMonths: server.termMonths,
126	      extraDiskGB: server.extraDiskGB,
127	      plan: { name: server.plan.name, priceCents: server.plan.priceCents },
128	      // A game server is sold at its game plan's flat price, NOT the base VPS
129	      // plan it happens to be built on. Omitting this quoted an $8.99 renewal for
130	      // a $4.99 product.
131	      gamePlan: server.gamePlan
132	        ? { name: server.gamePlan.name, priceCents: server.gamePlan.priceCents, termMonths: server.gamePlan.termMonths }
133	        : null,
134	      dedicatedIp: server.dedicatedIp,
135	      backupTier: server.backupTier,
136	    },
137	    {
138	      ipMonthlyCents: server.dedicatedIp ? await dedicatedIpMonthlyCents() : 0,
139	      extraDiskPerGbCents: extraDiskPriceCents,
140	      backupPlusCents,
141	      annualDiscountPct: annualPct,
142	      // VAT/GST for the owner (Finding 1): the "Renews at $X" figure and the Renew
143	      // now quote are tax-inclusive, matching what renewNow charges.
144	      taxRatePercent: renewTaxCtx.ratePercent,
145	    },
146	  );
147	
148	  // The server's REAL disk: plan allowance + any separately-purchased extra disk.
149	  // Every disk figure on this page uses this, never `plan.diskGB` on its own.
150	  const totalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
151	
152	  const publicIp = process.env.PUBLIC_IP ?? "";
153	  const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(server.status);
154	  const busy =
155	    transitional || server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");
156	  const steady = ["RUNNING", "STOPPED"].includes(server.status);
157	
158	  let live: LiveStats = null;
159	  let snapshots: { name: string; snaptime?: number; description?: string }[] = [];
160	  let backups: { volid: string; ctime?: number; size?: number }[] = [];
161	  let pveUnavailable = false;
162	
163	  if (server.vmid && steady) {
164	    const results = await Promise.allSettled([
165	      vmStatus(server.vmid),
166	      listSnapshots(server.vmid),
167	      listBackups(server.vmid),
168	    ]);
169	    if (results[0].status === "fulfilled") live = results[0].value as LiveStats;
170	    if (results[1].status === "fulfilled") snapshots = results[1].value as typeof snapshots;
171	    if (results[2].status === "fulfilled") backups = results[2].value as typeof backups;
172	    pveUnavailable = results.some((r) => r.status === "rejected");
173	  }
174	
175	  const sshCommand = server.sshPort ? `ssh root@${publicIp} -p ${server.sshPort}` : null;
176	
177	  // Single-item terminal list for this server — connect string computed the
178	  // same way as the Claude Code hub (dedicated IP → own IP, else NAT SSH port).
179	  const terminalServers = [
180	    {
181	      id: server.id,
182	      hostname: server.hostname,
183	      connect: server.dedicatedIp
184	        ? `ssh root@${server.dedicatedIp.address}`
185	        : `ssh -p ${server.sshPort ?? 22} root@${publicIp || "YOUR_SERVER_IP"}`,
186	    },
187	  ];
188	
189	  // SFTP/SSH connection details: dedicated-IP servers connect to their own IP on
190	  // port 22; NAT servers use the platform public IP + the forwarded SSH port.
191	  const dedicated = !!server.dedicatedIp;
192	  const sftpHost = dedicated ? server.dedicatedIp!.address : publicIp || null;
193	  const sftpPort = dedicated ? 22 : server.sshPort;
194	  const isGameServer = GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
195	
196	  // Per-game customization (only for game servers with a customization schema).
197	  const gameFamily = familyFor(server);
198	  const gameSchema = schemaFor(gameFamily);
199	  const gameVariant =
200	    gameSchema && server.gameVariant && isValidVariant(gameFamily!, server.gameVariant)
201	      ? server.gameVariant
202	      : gameSchema?.defaultVariant ?? "";
203	  const gameValidated = gameFamily
204	    ? validateConfig(gameFamily, (server.gameConfig as Record<string, unknown> | null) ?? {})
205	    : null;
206	  const gameValues = gameValidated && gameValidated.ok ? gameValidated.values : {};
207	
208	  /* ---------- Tab: Overview ---------- */
209	  const overview = (
210	    // `grid-cols-1` is load-bearing below `md`. With no base template the browser
211	    // creates an IMPLICIT `auto` track, sized to min-content and unclampable: at
212	    // 390px the rehearsal measured it at 530px — the `ssh root@… -p …` <code> and
213	    // the SFTP/SSH credentials are unbreakable strings — scrolling the whole page
214	    // 156px sideways. `grid-cols-1` compiles to `repeat(1, minmax(0, 1fr))`, the
215	    // same minmax `md:grid-cols-2` already applies, which is why desktop was fine.
216	    <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
217	      <div className="card">
218	        <h2 className="mb-4 font-semibold">Access</h2>
219	        <dl className="space-y-3 text-sm">
220	          <div>
221	            <dt className="text-slate-400">SSH command</dt>
222	            <dd className="mt-1 flex items-center gap-2">
223	              {/* min-w-0 + overflow-x-auto so a long/IPv6 SSH command scrolls
224	                  inside its own box instead of widening the card at 390px —
225	                  parity with the hardened SftpAccess command strings. */}
226	              <code className="min-w-0 flex-1 overflow-x-auto whitespace-nowrap rounded-lg border border-white/10 bg-navy-950/80 px-2.5 py-1.5 font-mono text-xs">
227	                {sshCommand ?? "provisioning…"}
228	              </code>
229	              {sshCommand && <CopyText text={sshCommand} />}
230	            </dd>
231	          </div>
232	          <div className="flex items-center justify-between">
233	            <dt className="text-slate-400">Root password</dt>
234	            <dd>
235	              {rootPassword ? (
236	                <RevealPassword password={rootPassword} />
237	              ) : (
238	                <span className="text-slate-500">—</span>
239	              )}
240	            </dd>
241	          </div>
242	          <div className="flex items-center justify-between">
243	            <dt className="text-slate-400">Private IP</dt>
244	            <dd className="font-mono text-xs">{server.ipAddress ?? "—"}</dd>
245	          </div>
246	        </dl>
247	        <div className="divider" />
248	        <div className="flex flex-wrap items-center justify-between gap-2">
249	          <p className="text-xs text-slate-500">
250	            Lost access or rotating credentials? Generate a fresh root password.
251	          </p>
252	          <ResetPasswordButton serverId={server.id} disabled={busy || !steady} />
253	        </div>
254	      </div>
255	
256	      <SftpAccess
257	        host={sftpHost}
258	        port={sftpPort}
259	        password={rootPassword}
260	        dedicated={dedicated}
261	      />
262	
263	      {isGameServer && (
264	        <div className="md:col-span-2">
265	          <GameAutoUpdate
266	            serverId={server.id}
267	            gameName={server.osTemplate.name}
268	            autoUpdate={server.autoUpdate}
269	            canUpdate={server.status === "RUNNING"}
270	            busy={busy}
271	          />
272	        </div>
273	      )}
274	
275	      {server.gamePlanId && gameSchema && (
276	        <div className="md:col-span-2">
277	          <GameSettings
278	            serverId={server.id}
279	            schema={gameSchema}
280	            variant={gameVariant}
281	            values={gameValues}
282	            disabled={busy || !steady}
283	          />
284	        </div>
285	      )}
286	
287	      <div className="card">
288	        <h2 className="mb-4 font-semibold">Live stats</h2>
289	        {live ? (
290	          <div className="space-y-4 text-sm">
291	            <div>
292	              <div className="mb-1.5 flex justify-between">
293	                <span className="text-slate-400">CPU</span>
294	                <span className="font-semibold">{((live.cpu ?? 0) * 100).toFixed(1)}%</span>
295	              </div>
296	              <MeterBar value={(live.cpu ?? 0) * 100} max={100} />
297	            </div>
298	            <div>
299	              <div className="mb-1.5 flex justify-between">
300	                <span className="text-slate-400">Memory</span>
301	                <span className="font-semibold">
302	                  {fmtBytes(live.mem ?? 0)} / {fmtBytes(live.maxmem ?? 0)}
303	                </span>
304	              </div>
305	              <MeterBar value={live.mem ?? 0} max={live.maxmem ?? 1} color="#3b82f6" />
306	            </div>
307	            <div className="flex justify-between">
308	              <span className="text-slate-400">Uptime</span>
309	              <span className="font-semibold">{fmtUptime(live.uptime ?? 0)}</span>
310	            </div>
311	            <div className="flex justify-between">
312	              <span className="text-slate-400">Network I/O</span>
313	              <span className="font-mono text-xs">
314	                {fmtBytes(live.netin ?? 0)} in · {fmtBytes(live.netout ?? 0)} out
315	              </span>
316	            </div>
317	          </div>
318	        ) : (
319	          <p className="text-sm text-slate-400">
320	            {pveUnavailable
321	              ? "Hypervisor is briefly unavailable — stats will reappear shortly."
322	              : "Live stats appear once the server is provisioned."}
323	          </p>
324	        )}
325	      </div>
326	
327	      <div className="card">
328	        <h2 className="mb-4 font-semibold">Configuration</h2>
329	        <dl className="space-y-2.5 text-sm">
330	          <div className="flex justify-between">
331	            <dt className="text-slate-400">Plan</dt>
332	            <dd>
333	              {server.plan.name} — {server.plan.cpuCores} vCPU / {server.plan.ramMB / 1024} GB /{" "}
334	              {totalDiskGB} GB NVMe
335	              {server.extraDiskGB > 0 && (
336	                <span className="block text-xs text-slate-500">
337	                  {server.plan.diskGB} GB plan + {server.extraDiskGB} GB added storage
338	                </span>
339	              )}
340	            </dd>
341	          </div>
342	          <div className="flex justify-between">
343	            <dt className="text-slate-400">Bandwidth</dt>
344	            <dd>{server.plan.bandwidthTB} TB / month</dd>
345	          </div>
346	          <div className="flex justify-between">
347	            <dt className="text-slate-400">Operating system</dt>
348	            <dd>{server.osTemplate.name}</dd>
349	          </div>
350	          <div className="flex justify-between">
351	            <dt className="text-slate-400">Created</dt>
352	            <dd>{server.createdAt.toISOString().slice(0, 10)}</dd>
353	          </div>
354	          <div className="flex justify-between">
355	            <dt className="text-slate-400">{server.isFree ? "Billing" : "Renews"}</dt>
356	            <dd>
357	              {server.isFree
358	                ? "Free — never expires"
359	                : server.expiresAt
360	                  ? server.expiresAt.toISOString().slice(0, 10)
361	                  : "—"}
362	            </dd>
363	          </div>
364	        </dl>
365	      </div>
366	
367	      {!server.isFree ? (
368	        // The "Price /mo" the card shows must agree with what Renew now charges.
